from typing import Protocol, runtime_checkable


@runtime_checkable
class UrunRepository(Protocol):
    def listele(self) -> list[dict[str, object]]:
        ...


class BellekRepository:
    def __init__(self, veriler: list[dict[str, object]]):
        self._veriler = list(veriler)

    def listele(self) -> list[dict[str, object]]:
        return list(self._veriler)


def repository_raporu(veriler: list[dict[str, object]]) -> list[str]:
    repository: UrunRepository = BellekRepository(veriler)
    return sorted(str(urun["ad"]) for urun in repository.listele())


